import{_ as i,C as l,o as n,c as g,a0 as o,b as a,w as t,a as c,E as d,a1 as r}from"./chunks/framework.DhQjJcnt.js";const A=JSON.parse('{"title":"Docs (resource)","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/docs.md","filePath":"artifacts/docs.md"}'),h={name:"artifacts/docs.md"};function p(u,e,m,b,k,f){const s=l("Mermaid");return n(),g("div",null,[e[2]||(e[2]=o(`<h1 id="docs-resource" tabindex="-1">Docs (resource) <a class="header-anchor" href="#docs-resource" aria-label="Permalink to &quot;Docs (resource)&quot;">​</a></h1><p>Vai trò <strong>Docs</strong> trong dự án (SSOT nghiệp vụ, cập nhật docs trước khi sửa nhóm resource khác): <a href="./">index.md</a>. Trang này mô tả <strong>chuẩn nội dung và cấu trúc</strong> của nhóm <strong>docs</strong> trên disk.</p><p><strong>Docs</strong> là artifacts resource chứa <strong>tài liệu đặc tả và kiến trúc</strong> — phạm vi, actor, module, chức năng, hợp đồng API trên tài liệu, business-process, deployment, open question, technical debt / derived / external call, … Trong README hoặc wizard init, root kiểu <strong>docs-hub</strong> chỉ là tên thường gặp khi repo <strong>chuyên document</strong>; SSOT mới gọi thống nhất <strong>docs resource</strong>, dù root nằm repo riêng hay thư mục trong repo FE.</p><hr><h2 id="docs-chua-nhung-gi" tabindex="-1">Docs chứa những gì? <a class="header-anchor" href="#docs-chua-nhung-gi" aria-label="Permalink to &quot;Docs chứa những gì?&quot;">​</a></h2><p>Trên <strong>cùng một cây docs</strong> (không phải hai repo):</p><ul><li><strong>Overview:</strong> operating model — actor, operational area, phạm vi.</li><li><strong>Surfaces:</strong> <strong>SSOT cả team tham chiếu</strong> — nghiệp vụ, module, chức năng, bundle, API spec trên docs, <code>FLOW-*</code> product; ngôn ngữ product, kỹ thuật chỉ mức team hiểu chung (lưu đâu, bucket nào…).</li><li><strong>Architecture:</strong> <strong>kiến giải kỹ thuật</strong> — phải <strong>detail</strong> cách hệ thống triển khai (service, gateway, CDN, data, integration, <code>DEP-*</code>).</li></ul><p><strong>Web / Client / API</strong> là kênh trong cây Surfaces, không đồng nghĩa operational area.</p><p>PM/Leader <strong>không bắt buộc</strong> lấp đầy toàn bộ cây một lần — hoàn thiện cuốn chiếu theo giai đoạn.</p><h3 id="cay-layer-đieu-huong-noi-dung" tabindex="-1">Cây layer (điều hướng nội dung) <a class="header-anchor" href="#cay-layer-đieu-huong-noi-dung" aria-label="Permalink to &quot;Cây layer (điều hướng nội dung)&quot;">​</a></h3><p>Root = <strong>docs resource</strong> (<code>FLOWGRID_DOCS_ROOT</code> / <code>.flowgrid/config.json</code>). Path vật lý dưới root (không dùng <code>modules/</code>, <code>docs/features/</code>, <code>shared/</code> ad-hoc):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;CATALOG.md&gt;                         # publish — mục lục GitHub / site</span></span>
<span class="line"><span>index.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>overview/</span></span>
<span class="line"><span>├─ index.md                          # purpose, scope, actor, assumptions</span></span>
<span class="line"><span>└─ operational-areas/</span></span>
<span class="line"><span>   └─ &lt;area&gt;.md                      # Admin ops, shop-floor, …</span></span>
<span class="line"><span></span></span>
<span class="line"><span>surfaces/                            # SSOT product + spec — cả team đọc/sửa đây</span></span>
<span class="line"><span>├─ common/                           # scope system — folder chỉ khi có artifact</span></span>
<span class="line"><span>│  ├─ processes/                     # FLOW-* (nghiệp vụ, product)</span></span>
<span class="line"><span>│  ├─ data-model/                    # model / ERD mức product (nếu cần)</span></span>
<span class="line"><span>│  ├─ integrations/                  # luồng đối tác mức product (nếu cần)</span></span>
<span class="line"><span>│  ├─ yaml/                          # LCA common — *.bundle.yaml + ir/</span></span>
<span class="line"><span>│  ├─ md/                            # prose common (generated / hand)</span></span>
<span class="line"><span>│  ├─ code/                          # UI-CMN-* · API-CMN-* registry</span></span>
<span class="line"><span>│  └─ patterns/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ &lt;surface&gt;/                        # vd. admin-web · line-client · integration-gateway</span></span>
<span class="line"><span>│  ├─ common/                        # scope surface — cùng pattern common (khi có)</span></span>
<span class="line"><span>│  └─ CMP-*/                         # module — một owner surface giữ SSOT</span></span>
<span class="line"><span>│     ├─ README.md                   # ownership, boundary, dependency</span></span>
<span class="line"><span>│     ├─ common/                     # scope module (processes/FLOW-*, data-model, …)</span></span>
<span class="line"><span>│     └─ &lt;NN&gt;/&lt;NN&gt;/…/                # function leaf — cluster số (nav: Functions)</span></span>
<span class="line"><span>│        ├─ &lt;slug&gt;.bundle.yaml       # authoring SSOT</span></span>
<span class="line"><span>│        ├─ ir/</span></span>
<span class="line"><span>│        │  ├─ design.yaml</span></span>
<span class="line"><span>│        │  ├─ spec.yaml</span></span>
<span class="line"><span>│        │  └─ generated/&lt;slug&gt;.md</span></span>
<span class="line"><span>│        ├─ api/&lt;seq&gt;/</span></span>
<span class="line"><span>│        │  ├─ 01-backend-spec.yaml</span></span>
<span class="line"><span>│        │  ├─ 02-openapi.yaml</span></span>
<span class="line"><span>│        │  └─ 03-mock.yaml          # tùy stack</span></span>
<span class="line"><span>│        └─ qa/</span></span>
<span class="line"><span>│           ├─ open/QA-*.yaml</span></span>
<span class="line"><span>│           └─ index.md</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ &lt;surface-khác&gt;/                   # không owner: link/map sang CMP-* owner, không copy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>architecture/                        # kiến giải kỹ thuật — detail how (Markdown + Mermaid)</span></span>
<span class="line"><span>├─ business-process · FLOW-*         # → thường architecture/03-business-process/</span></span>
<span class="line"><span>├─ data model / database             # overview kỹ thuật (chapter tương ứng khi có)</span></span>
<span class="line"><span>├─ cross-service · integrations</span></span>
<span class="line"><span>├─ deployment · DEP-*                # → thường architecture/07-deployment/</span></span>
<span class="line"><span>├─ decisions · ADR-*                 # → thường architecture/09-decisions/</span></span>
<span class="line"><span>└─ …                                 # folder chapter khác từ init skeleton — stub đến khi cần</span></span></code></pre></div><p><strong>Nav vs disk:</strong> site/VitePress dùng nhãn nghiệp vụ (Overview, Surfaces, Modules, Functions); <code>flowgrid init</code> có thể tạo leaf dưới tên slug — <strong>contract path</strong> vẫn là <code>surfaces/&lt;owner&gt;/CMP-*/…</code> + bundle/IR/API như trên.</p><p><strong><code>Common?</code> (system / surface / module):</strong> node <strong>động</strong> — có folder khi scope thật sự có artifact; rỗng thì ẩn trên nav.</p><p><strong>Module (<code>CMP-*</code>):</strong> một <strong>owner surface</strong>; surface khác chỉ <strong>link/map</strong>.</p><p><strong>Function:</strong> không có folder tên <code>functions/</code>; leaf = <code>CMP-*/&lt;NN…&gt;/</code> (+ file trong leaf, xem <a href="#function-leaf--layout-chuẩn">Function leaf</a>).</p><h2 id="architecture-va-surfaces-—-khac-nhau-the-nao" tabindex="-1">Architecture và Surfaces — khác nhau thế nào? <a class="header-anchor" href="#architecture-va-surfaces-—-khac-nhau-the-nao" aria-label="Permalink to &quot;Architecture và Surfaces — khác nhau thế nào?&quot;">​</a></h2><p><strong>Tóm lại:</strong> <strong>Surfaces</strong> = tài liệu <strong>SSOT</strong> mà cả team (BA, PO, dev, QA) tham chiếu khi làm feature; <strong>Architecture</strong> = <strong>kiến giải kỹ thuật</strong> — phải mô tả <strong>chi tiết</strong> hệ thống sẽ/build như thế nào (không thay spec product trong Surfaces).</p><h3 id="surfaces-—-ngon-ngu-product-business" tabindex="-1">Surfaces — ngôn ngữ product / business <a class="header-anchor" href="#surfaces-—-ngon-ngu-product-business" aria-label="Permalink to &quot;Surfaces — ngôn ngữ product / business&quot;">​</a></h3><ul><li><strong>Surface</strong> là góc nhìn <strong>sản phẩm</strong> theo kênh (Admin Web, Line Client, …): module (<code>CMP-*</code>), function, bundle — nơi mô tả <strong>hành vi nghiệp vụ</strong>, actor, rule, acceptance cho stakeholder.</li><li>Viết để BA / PO / dev hiểu <strong>làm gì, vì sao, ai dùng</strong> — không phải sơ đồ hạ tầng.</li><li>Khi cần nhắc kỹ thuật trong Surfaces, chỉ ở mức <strong>product hiểu được</strong>, ví dụ: “file đính kèm <strong>lưu trên S3</strong> bucket <code>reports-prod</code>”, “gọi dịch vụ thanh toán bên thứ ba” — <strong>không</strong> mô tả gateway, CDN, subnet, IAM policy, sequence diagram service nội bộ.</li><li>Cấu trúc: <strong>Common?</strong> → <strong>Modules</strong> → <strong>Functions</strong>; <code>FLOW-*</code> và business-process <strong>chi tiết nghiệp vụ</strong> (actor, bước, outcome, exception) nằm ở <strong>Common theo scope</strong> (<code>surfaces/common/…</code>, <code>surfaces/&lt;surface&gt;/common/…</code>, <code>…/CMP-*/common/processes/FLOW-*.md</code>) — vẫn là <strong>ngôn ngữ product</strong>, kể cả khi có một dòng “lưu S3”.</li></ul><h3 id="architecture-—-thuan-ky-thuat" tabindex="-1">Architecture — thuần kỹ thuật <a class="header-anchor" href="#architecture-—-thuan-ky-thuat" aria-label="Permalink to &quot;Architecture — thuần kỹ thuật&quot;">​</a></h3><ul><li>Nhánh <strong>Architecture</strong> mô tả <strong>hệ thống chạy thế nào</strong>: service nào gọi service nào, data model kỹ thuật, integration contract, <strong>deployment</strong> (<code>DEP-*</code>), topology.</li><li>Cùng ví dụ S3: Architecture ghi <strong>đường đi kỹ thuật</strong> — upload qua <strong>API gateway</strong> nào, <strong>CDN</strong> có hay không, presigned URL, queue, worker, region, backup — không viết lại user story product.</li><li><code>architecture/03-business-process/FLOW-*.md</code> là <strong><code>FLOW-*</code> ở góc kỹ thuật</strong> — luồng xử lý qua component/hệ thống (curated, xuyên sản phẩm), <strong>không</strong> thay bản kể nghiệp vụ trong Surfaces.</li><li>Các chương Architecture khác (data, integration, deployment) cùng nguyên tắc: <strong>how</strong>, không <strong>what</strong> product.</li></ul><h3 id="so-sanh-nhanh-cung-chu-đe-hai-layer" tabindex="-1">So sánh nhanh (cùng chủ đề, hai layer) <a class="header-anchor" href="#so-sanh-nhanh-cung-chu-đe-hai-layer" aria-label="Permalink to &quot;So sánh nhanh (cùng chủ đề, hai layer)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chủ đề</th><th>Surfaces (product)</th><th>Architecture (kỹ thuật)</th></tr></thead><tbody><tr><td>Lưu file</td><td>“User upload báo cáo; file lưu S3 bucket X”</td><td>Client → API → auth → S3 qua gateway Y; virus scan; lifecycle policy</td></tr><tr><td>Luồng nghiệp vụ</td><td><code>FLOW-*</code> trong Common: bước business, actor, rule</td><td><code>FLOW-*</code> trong <code>03-business-process</code>: bước system, service, queue, API</td></tr><tr><td>API / data</td><td>Contract trên bundle + <code>01-backend-spec</code> (spec chức năng)</td><td>Data model, cross-service flow, integration diagram</td></tr><tr><td>Triển khai</td><td>(thường không chi tiết)</td><td><code>DEP-*</code>, môi trường, network</td></tr></tbody></table><h3 id="flow-—-hai-home-mot-ma-khong-trung-vai-tro" tabindex="-1"><code>FLOW-*</code> — hai home, một mã, không trùng vai trò <a class="header-anchor" href="#flow-—-hai-home-mot-ma-khong-trung-vai-tro" aria-label="Permalink to &quot;\`FLOW-*\` — hai home, một mã, không trùng vai trò&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Home</th><th>Path</th><th>Ngôn ngữ &amp; nội dung</th></tr></thead><tbody><tr><td><strong>Surfaces / Common</strong></td><td><code>surfaces/.../common/…</code>, <code>…/CMP-*/common/processes/FLOW-*.md</code></td><td><strong>Product:</strong> luồng nghiệp vụ chi tiết; tech chỉ <strong>mức chung</strong> (có S3, có gọi đối tác)</td></tr><tr><td><strong>Architecture §03</strong></td><td><code>architecture/03-business-process/FLOW-*.md</code></td><td><strong>Kỹ thuật:</strong> luồng qua hệ thống; gateway, service, integration — curated toàn sản phẩm</td></tr></tbody></table><p><strong>Write rule:</strong></p><ul><li>Cùng mã <code>FLOW-*</code> được <strong>link</strong> giữa product (Surfaces) và technical (Architecture) — <strong>không</strong> copy hai bản mô tả khác nghĩa rồi gọi là SSOT.</li><li>Sửa <strong>nghiệp vụ</strong> (bước user, rule) → Surfaces / bundle trước; sửa <strong>triển khai</strong> (service, gateway) → Architecture.</li><li>Function <strong>bundle</strong> là spec màn/API (product + design kỹ thuật UI/field); không thay file <code>FLOW-*</code> Surfaces hay Architecture.</li></ul><h3 id="loai-artifact-thuong-gap-trong-docs" tabindex="-1">Loại artifact thường gặp trong docs <a class="header-anchor" href="#loai-artifact-thuong-gap-trong-docs" aria-label="Permalink to &quot;Loại artifact thường gặp trong docs&quot;">​</a></h3><ul><li><strong>Overview:</strong> purpose, operational areas, actor.</li><li><strong>Surfaces (SSOT):</strong> module, bundle, IR, API spec, QA, <code>FLOW-*</code> product, common registry.</li><li><strong>Architecture (kỹ thuật):</strong> <code>FLOW-*</code> system view, data/integration/deployment detail, <code>DEP-*</code>, ADR.</li><li><strong>Đặc tả chức năng:</strong> user story, acceptance, rule nghiệp vụ; <strong>bundle</strong> + IR cho từng màn/API.</li><li><strong>Thiết kế hành vi UI:</strong> <code>bundle.design</code>, state/action, matrix — input cho prototype và codegen FE.</li><li><strong>Hợp đồng API (trên docs):</strong> <code>api/&lt;seq&gt;/01-backend-spec.yaml</code> (+ openapi, mock) — SSOT BE, không gộp vào <code>bundle.spec.api</code>.</li><li><strong>QA:</strong> <code>qa/open/QA-*.yaml</code>, <code>qa/index.md</code> — câu hỏi treo đến khi resolve.</li><li><strong>Chất lượng &amp; phụ thuộc:</strong> technical debt, derived requirement, call external service — markers/section trên bundle hoặc common theo scope.</li><li><strong>Xuất bản đọc cho người:</strong> <code>ir/generated/&lt;slug&gt;.md</code>, site VitePress (khi dùng), <code>CATALOG.md</code> — <strong>sinh từ</strong> SSOT authoring, không thay bundle.</li></ul><h3 id="id-chuan-resolve-codegen-test-audit" tabindex="-1">ID chuẩn (resolve codegen / test / audit) <a class="header-anchor" href="#id-chuan-resolve-codegen-test-audit" aria-label="Permalink to &quot;ID chuẩn (resolve codegen / test / audit)&quot;">​</a></h3><p><code>CMP-*</code> · <code>W-*</code> · <code>API-*</code> · <code>FLOW-*</code> · <code>DEP-*</code> · <code>SC-*</code> · <code>TC-*</code> (trace) · <code>UI-CMN-*</code> / <code>API-CMN-*</code> (common registry).</p><p>Công cụ FE/BE/Test ưu tiên resolve theo ID và path chuẩn; <code>DEP-*</code> chỉ cho deployment, không thay target màn hình. <strong>Không</strong> dùng <code>CTR-*</code> / ID Context-Containers cũ trên public contract; <code>W-*</code> / <code>API-*</code> / bundle <strong>chỉ</strong> dưới <code>surfaces/</code>.</p><hr><h2 id="trien-khai-root" tabindex="-1">Triển khai root <a class="header-anchor" href="#trien-khai-root" aria-label="Permalink to &quot;Triển khai root&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kiểu</th><th>Khi dùng</th></tr></thead><tbody><tr><td><strong>Repo document riêng</strong></td><td>Team tách hub spec; <code>flowgrid init</code> type <strong>Document</strong>, hoặc FE/BE/Fullstack trỏ docs root sang repo/path khác.</td></tr><tr><td><strong>Docs in-repo</strong></td><td>Dự án nhỏ: <code>docs/</code>, <code>documentation/</code> trong repo FE — vẫn là <strong>docs resource</strong> về nghĩa, chỉ gom vật lý.</td></tr></tbody></table><h3 id="flowgrid" tabindex="-1">FlowGrid <a class="header-anchor" href="#flowgrid" aria-label="Permalink to &quot;FlowGrid&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>FLOWGRID_DOCS_ROOT</code></td><td>Root docs resource (CLI, engine, MCP).</td></tr><tr><td><code>.flowgrid/config.json</code></td><td>Ghi path docs sau <code>init</code>.</td></tr><tr><td>Type <strong>Document</strong></td><td>cwd thường = docs root; wizard hỏi <strong>đa ngôn ngữ global</strong> của dự án (locale/i18n áp cho toàn hệ thống — UI, label trong bundle, app; <strong>không</strong> phải “tài liệu tiếng Anh / tiếng Pháp” riêng từng file). Khai báo vd. <code>vi,en,ja</code> + locale mặc định; chỉ một ngôn ngữ thì nhập một.</td></tr></tbody></table><p>Chi tiết flag CLI &amp; init: <a href="./../references/cli-and-commands.html">references/cli-and-commands.md</a>.</p><hr><h2 id="function-leaf-—-layout-chuan" tabindex="-1">Function leaf — layout chuẩn <a class="header-anchor" href="#function-leaf-—-layout-chuan" aria-label="Permalink to &quot;Function leaf — layout chuẩn&quot;">​</a></h2><p>Một chức năng (màn / API primary entity) nằm dưới <code>surfaces/&lt;owner-surface&gt;/CMP-*/&lt;NN…&gt;/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;slug&gt;.bundle.yaml          # authoring SSOT (sửa tay tại đây)</span></span>
<span class="line"><span>ir/</span></span>
<span class="line"><span>  design.yaml               # tech IR — FE codegen + bộ test đọc lane design</span></span>
<span class="line"><span>  spec.yaml                 # business prose (split từ bundle)</span></span>
<span class="line"><span>  generated/&lt;slug&gt;.md     # Markdown site / catalog (render)</span></span>
<span class="line"><span>api/&lt;seq&gt;/</span></span>
<span class="line"><span>  01-backend-spec.yaml      # API SSOT</span></span>
<span class="line"><span>  02-openapi.yaml</span></span>
<span class="line"><span>  03-mock.yaml              # tùy stack</span></span>
<span class="line"><span>qa/open/QA-&lt;id&gt;-NNNN.yaml   # optional inbox</span></span></code></pre></div><p><strong>Không</strong> dùng path <code>modules/</code> trên disk, <strong>không</strong> <code>code/W-*</code> / <code>code/API-*</code> sát leaf (nav “Functions” ≠ folder <code>functions/</code>). Cluster số: <code>CMP-*/&lt;NN&gt;/&lt;NN&gt;/…/</code> (vd. <code>01/01/01/</code>).</p><h3 id="leaf-→-split-render-repo-code-publish" tabindex="-1">Leaf → split, render, repo code, publish <a class="header-anchor" href="#leaf-→-split-render-repo-code-publish" aria-label="Permalink to &quot;Leaf → split, render, repo code, publish&quot;">​</a></h3>`,45)),(n(),a(r,null,{default:t(()=>[d(s,{id:"mermaid-391",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20leaf%5B%22surfaces%2F%26lt%3Bsurface%26gt%3B%2FCMP-*%2F%26lt%3BNN%E2%80%A6%26gt%3B%2F%22%5D%0A%20%20%20%20BUNDLE%5B%22%26lt%3Bslug%26gt%3B.bundle.yaml%5Cnauthoring%20SSOT%22%5D%0A%20%20%20%20IRD%5B%22ir%2Fdesign.yaml%22%5D%0A%20%20%20%20IRS%5B%22ir%2Fspec.yaml%22%5D%0A%20%20%20%20IRG%5B%22ir%2Fgenerated%2F%26lt%3Bslug%26gt%3B.md%22%5D%0A%20%20%20%20API%5B%22api%2F%26lt%3Bseq%26gt%3B%2F01%20%C2%B7%2002%20%C2%B7%2003%22%5D%0A%20%20end%0A%20%20QA%5B%22qa%2Fopen%2FQA-*.yaml%5Cnqa%2Findex.md%22%5D%0A%20%20BUNDLE%20--%3E%7Cspec%3Asplit%7C%20IRD%0A%20%20BUNDLE%20--%3E%7Cspec%3Asplit%7C%20IRS%0A%20%20IRS%20--%3E%7Crender%7C%20IRG%0A%20%20IRD%20--%3E%7Cb%E1%BB%99%20code%20FE%20%2B%20b%E1%BB%99%20test%7C%20FE%5B%22FE%20repo%22%5D%0A%20%20API%20--%3E%7Cb%E1%BB%99%20code%20BE%7C%20BE%5B%22BE%20repo%22%5D%0A%20%20QA%20--%3E%7Crender%7C%20QAL%5B%22qa%2Findex.md%22%5D%0A%20%20IRG%20--%3E%7Cpublish%7C%20CAT%5B%22CATALOG.md%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<table tabindex="0"><thead><tr><th>Path (docs hub)</th><th>Vai trò</th></tr></thead><tbody><tr><td><code>*.bundle.yaml</code></td><td>Authoring SSOT (business + tech trên cùng file)</td></tr><tr><td><code>ir/design.yaml</code></td><td>Tech IR — input <strong>FE</strong> codegen + lane design trên tests</td></tr><tr><td><code>ir/spec.yaml</code></td><td>Business inventory — publish qua <code>ir/generated</code></td></tr><tr><td><code>ir/generated/&lt;slug&gt;.md</code></td><td>Markdown site / GitHub đọc</td></tr><tr><td><code>api/&lt;seq&gt;/01-backend-spec.yaml</code></td><td>API SSOT (một API / một primary entity)</td></tr><tr><td><code>api/&lt;seq&gt;/02-openapi.yaml</code></td><td><code>flowgrid openapi_render</code> / gen OpenAPI</td></tr><tr><td><code>api/&lt;seq&gt;/03-mock.yaml</code></td><td>Mock contract (tùy stack)</td></tr><tr><td><code>surfaces/…/common/yaml/</code></td><td>LCA common (FE bundle + <code>ir/design.yaml</code>; API common = trio tại slug common)</td></tr><tr><td><code>architecture/03-business-process/FLOW-*.md</code></td><td>Catalog FLOW kỹ thuật; module-internal: <code>…/CMP-*/common/processes/FLOW-*.md</code></td></tr><tr><td><code>qa/open/</code> · <code>qa/index.md</code></td><td>Inbox + list (<code>render</code> luôn ghi list, kể cả rỗng)</td></tr><tr><td><code>CATALOG.md</code> (repo root docs)</td><td>Mục lục — <code>flowgrid publish</code></td></tr></tbody></table><p>Pattern CRUD mẫu (sau <code>flowgrid init</code>): <code>templates/shared/patterns/admin-crud.pattern.yaml</code>.</p><h3 id="bundle-↔-ir-split-render" tabindex="-1">Bundle ↔ IR (split &amp; render) <a class="header-anchor" href="#bundle-↔-ir-split-render" aria-label="Permalink to &quot;Bundle ↔ IR (split &amp; render)&quot;">​</a></h3>',3)),(n(),a(r,null,{default:t(()=>[d(s,{id:"mermaid-500",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22*.bundle.yaml%5Cnspec%20%C2%B7%20gen%20%C2%B7%20design%22%5D%0A%20%20S%5B%22spec%3Asplit%20%2F%20flowgrid%20split%22%5D%0A%20%20M%5B%22spec%3Amerge%20%2F%20flowgrid%20merge%22%5D%0A%20%20IR_D%5B%22ir%2Fdesign.yaml%5Cntech%20%2B%20FE%2FTest%22%5D%0A%20%20IR_S%5B%22ir%2Fspec.yaml%5Cnbusiness%20prose%22%5D%0A%20%20MD%5B%22ir%2Fgenerated%2F%3Cslug%3E.md%5CnData%20Dictionary%20%26%20State%20Matrix%22%5D%0A%20%20B%20--%3E%20S%20--%3E%20IR_D%0A%20%20B%20--%3E%20S%20--%3E%20IR_S%0A%20%20IR_S%20--%3E%7Crender%7C%20MD%0A%20%20IR_D%20--%3E%20M%20--%3E%20B%0A%20%20IR_S%20--%3E%20M%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<ul><li><strong>Không</strong> còn <code>ir/legacy.yaml</code>. Stub <code>legacy:</code> rỗng trên bundle bị bỏ lúc split.</li><li><strong>Không</strong> author <code>bundle.spec.api</code> — API SSOT là <code>api/&lt;seq&gt;/01-backend-spec.yaml</code>.</li></ul><h3 id="bundle-—-authoring-ssot-spec-·-gen-·-design" tabindex="-1">Bundle — authoring SSOT (<code>spec</code> · <code>gen</code> · <code>design</code>) <a class="header-anchor" href="#bundle-—-authoring-ssot-spec-·-gen-·-design" aria-label="Permalink to &quot;Bundle — authoring SSOT (`spec` · `gen` · `design`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Chứa</th><th>Ai sửa (skill)</th></tr></thead><tbody><tr><td><code>bundle.spec</code></td><td>Actors, requirements, <code>ui.list|form|detail</code>, acceptance — <strong>không</strong> <code>spec.api</code></td><td><code>/spec</code>, <code>/legacy /spec</code>, <code>/grill-bqa</code></td></tr><tr><td><code>bundle.gen</code></td><td><code>codegen.profile</code> / entity / module, <code>#gen:*</code>, <code>ui.filters</code> / columns</td><td><code>/grill-dev</code></td></tr><tr><td><code>bundle.design</code></td><td>nav, sections/items (label, meaning, purpose, 5-tier validation, widget specs), <code>stateMatrix</code>, actions (6 blocks + 4-tier outcomes)</td><td><code>/spec</code> + <code>/grill-dev</code></td></tr><tr><td><code>bundle.review</code></td><td>Prose BA — <strong>không</strong> split sang <code>ir/*</code></td><td><code>/grill-bqa</code></td></tr><tr><td><code>qa/open/QA-&lt;bundle.id&gt;-NNNN.yaml</code></td><td>Câu hỏi treo (AskQuestion / Other chưa chốt)</td><td><code>/qa-resolve</code> đóng</td></tr></tbody></table><p><strong>Quy tắc edit:</strong> sửa <strong><code>*.bundle.yaml</code></strong> (và/hoặc <code>01-backend-spec.yaml</code>), rồi <strong><code>flowgrid split</code></strong> / <code>pnpm spec:split</code>. <strong>Không</strong> sửa tay <code>ir/design.yaml</code> / <code>ir/spec.yaml</code> — split <strong>ghi đè</strong> IR. Grill ghi bundle (hoặc <code>01</code>) rồi split; merge đẩy <code>gen</code> / layout về bundle khi cần.</p><p><strong>Hướng dẫn author bundle (toolkit):</strong> quy ước <code>userStories</code> ↔ UX, ma trận action, checklist <code>/update-spec</code> — <a href="https://github.com/ShanYuCoder/flowgrid/blob/main/templates/shared/bundle-authoring.md" target="_blank" rel="noreferrer"><code>templates/shared/bundle-authoring.md</code></a> trong repo FlowGrid (sau <code>init</code>, template tương đương thường nằm <code>.flowgrid/templates/</code>). Đọc trên GitHub repo toolkit; trang VitePress không mirror file này.</p><h3 id="split-output-—-ai-đoc-file-nao" tabindex="-1">Split output — ai đọc file nào <a class="header-anchor" href="#split-output-—-ai-đoc-file-nao" aria-label="Permalink to &quot;Split output — ai đọc file nào&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Độc giả / mục đích</th></tr></thead><tbody><tr><td><code>*.bundle.yaml</code></td><td><strong>Authoring SSOT</strong>; <strong>tests-docs</strong> <code>/testcase</code> đọc <strong>cả bundle</strong> (không tách đọc <code>ir/spec</code> + <code>ir/design</code> riêng).</td></tr><tr><td><code>ir/design.yaml</code></td><td><strong>Bộ Code FE</strong> — <code>/prototype</code>, codegen; <code>api</code> slim tham chiếu từ <code>01</code> local khi cần.</td></tr><tr><td><code>ir/spec.yaml</code></td><td>Business prose (split từ bundle) — input cho render.</td></tr><tr><td><code>ir/generated/&lt;slug&gt;.md</code></td><td>Site + <code>flowgrid publish</code> — bảng Data Dictionary, State &amp; Permission Matrix, Action Flows (<strong>không</strong> dump raw YAML).</td></tr><tr><td><code>api/&lt;seq&gt;/01-backend-spec.yaml</code></td><td><strong>Bộ Code BE</strong> (<code>/api</code>) — <strong>không</strong> đọc <code>ir/*</code> cho contract API.</td></tr></tbody></table><h3 id="common-path-hop-le" tabindex="-1">Common (path hợp lệ) <a class="header-anchor" href="#common-path-hop-le" aria-label="Permalink to &quot;Common (path hợp lệ)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Path</th></tr></thead><tbody><tr><td>System</td><td><code>surfaces/common/</code></td></tr><tr><td>Surface</td><td><code>surfaces/&lt;surface&gt;/common/</code></td></tr><tr><td>Module</td><td><code>surfaces/&lt;owner-surface&gt;/CMP-*/common/</code></td></tr></tbody></table><p><strong>Cấm</strong> path ad-hoc: <code>shared/</code>, <code>common/</code> (root lẫn), <code>docs/common/</code>, <code>docs/features/</code>, <code>modules/</code> trên disk.</p><h3 id="write-rules-ssot-—-tom-tu-contract-docs" tabindex="-1">Write rules (SSOT) — tóm từ contract docs <a class="header-anchor" href="#write-rules-ssot-—-tom-tu-contract-docs" aria-label="Permalink to &quot;Write rules (SSOT) — tóm từ contract docs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chủ đề</th><th>Rule</th></tr></thead><tbody><tr><td><code>FLOW-*</code> product</td><td>SSOT nghiệp vụ: <code>surfaces/…/common/…</code> / <code>…/CMP-*/common/processes/</code> — link sang <code>architecture/03-business-process/FLOW-*</code> (kỹ thuật), không hai bản mâu thuẫn</td></tr><tr><td><code>FLOW-*</code> kỹ thuật</td><td><code>architecture/03-business-process/</code> (+ dynamic view trong <code>model/</code>) — sequence service/infra, không thay user journey trong Surfaces</td></tr><tr><td>Module</td><td>Một <code>CMP-*</code> → một owner <code>surfaces/&lt;owner&gt;/CMP-*</code>; surface khác <strong>link/map</strong></td></tr><tr><td>Function</td><td>Leaf <code>CMP-*/&lt;NN…&gt;/</code>; nav “Functions” ≠ folder <code>functions/</code></td></tr><tr><td>API contract</td><td><code>api/&lt;seq&gt;/01-backend-spec.yaml</code> — không gộp vào <code>bundle.spec.api</code>; Architecture <strong>không</strong> chứa endpoint spec (thuộc <code>/spec</code>)</td></tr><tr><td>Common registry</td><td><code>UI-CMN-*</code> / <code>API-CMN-*</code> under <code>surfaces/common/code/</code> (path có <code>/code/</code>)</td></tr><tr><td><code>DEP-*</code></td><td>Chỉ <code>architecture/07-deployment/</code> — không thay target màn <code>W-*</code></td></tr><tr><td>Diagram</td><td>Architecture: Mermaid <code>flowchart</code> / <code>sequenceDiagram</code> (luồng service/infra); Surfaces: sequence <strong>màn hình</strong> (skill <code>/business-process</code>), không HTTP verb chi tiết trong FLOW product</td></tr></tbody></table><hr><h2 id="yaml-va-markdown-trong-docs" tabindex="-1">YAML và Markdown trong docs <a class="header-anchor" href="#yaml-va-markdown-trong-docs" aria-label="Permalink to &quot;YAML và Markdown trong docs&quot;">​</a></h2><ul><li><strong>YAML (bundle, IR, API spec, QA):</strong> lớp <strong>máy</strong> — schema, audit, codegen, agent; diff field rõ.</li><li><strong>Markdown (generated, overview, FLOW, module README):</strong> lớp <strong>người</strong> — review PR, stakeholder, site docs.</li></ul><p>Excel/Docx vẫn có thể là deliverable khách hàng; <strong>SSOT kỹ thuật</strong> trong docs resource nên là YAML/Markdown có cấu trúc để export ngược chính xác.</p><hr><h2 id="lenh-docs-hub-split-·-merge-·-render-·-publish" tabindex="-1">Lệnh docs hub (split · merge · render · publish) <a class="header-anchor" href="#lenh-docs-hub-split-·-merge-·-render-·-publish" aria-label="Permalink to &quot;Lệnh docs hub (split · merge · render · publish)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lệnh (alias npm)</th><th>Mục đích</th></tr></thead><tbody><tr><td><code>flowgrid split</code> · <code>pnpm spec:split -- &lt;bundle.yaml&gt;</code></td><td>bundle → <code>ir/design.yaml</code> + <code>ir/spec.yaml</code> (+ chuỗi render MD khi chạy pipeline đầy đủ)</td></tr><tr><td><code>flowgrid merge</code> · <code>pnpm spec:merge -- &lt;bundle.yaml&gt;</code></td><td><code>ir/*</code> → bundle</td></tr><tr><td><code>flowgrid check</code> · <code>pnpm spec:split:check</code></td><td>CI: IR sync bundle; common yaml <strong>bắt buộc</strong> có <code>ir/design.yaml</code></td></tr><tr><td><code>flowgrid render</code> · <code>pnpm flowgrid:render</code></td><td><code>ir/spec.yaml</code> → <code>ir/generated/*.md</code>; luôn ghi <code>qa/index.md</code></td></tr><tr><td><code>flowgrid publish</code> · <code>pnpm flowgrid:publish</code></td><td><code>CATALOG.md</code> + link đầu README (<strong>không</strong> render lại spec)</td></tr></tbody></table><p>Audit spec trên bundle: <code>flowgrid audit spec</code> — <a href="./../references/cli-and-commands.html#audit--harness-pr-workflow">references/cli-and-commands.md</a>.</p><hr><h2 id="quan-he-voi-nhom-resource-khac" tabindex="-1">Quan hệ với nhóm resource khác <a class="header-anchor" href="#quan-he-voi-nhom-resource-khac" aria-label="Permalink to &quot;Quan hệ với nhóm resource khác&quot;">​</a></h2><ul><li><strong>Tests-docs:</strong> định nghĩa <strong>kiểm gì</strong>; trace về bundle/spec trong docs. Sai <strong>yêu cầu</strong> → sửa docs (và testcase) trước code.</li><li><strong>Code:</strong> implement FE/BE; đối chiếu <code>ir/design.yaml</code>, <code>01-backend-spec.yaml</code>, không “đoán” từ code khi đã có SSOT docs.</li><li><strong>DSL &amp; platform:</strong> markers (<code>#needs-component</code>, debt…), DNA, registry — <strong>định dạng và quy ước</strong>, không thay nội dung nghiệp vụ trong bundle.</li></ul><p>Thứ tự làm việc (skill, gate): <a href="./../workflows/">workflows</a>.</p>',24))])}const v=i(h,[["render",p]]);export{A as __pageData,v as default};
